import React, { useEffect, useRef } from "react";
import { MapContainer, TileLayer, GeoJSON, Popup, CircleMarker } from "react-leaflet";
import L from "leaflet";
import { Box, Typography, Chip, CircularProgress } from "@mui/material";
import "leaflet/dist/leaflet.css";

// Fix for default markers in react-leaflet
delete L.Icon.Default.prototype._getIconUrl;
L.Icon.Default.mergeOptions({
  iconRetinaUrl: require("leaflet/dist/images/marker-icon-2x.png"),
  iconUrl: require("leaflet/dist/images/marker-icon.png"),
  shadowUrl: require("leaflet/dist/images/marker-shadow.png"),
});

const MapVisualization = ({ stressData, ratingsData, loading }) => {
  const mapRef = useRef();

  // Hawaii bounds
  const hawaiiBounds = [
    [18.9, -160.2], // Southwest corner
    [22.3, -154.8], // Northeast corner
  ];

  const getStatusColor = (status) => {
    switch (status) {
      case "GOOD":
        return "#4caf50";
      case "WARN":
        return "#ff9800";
      case "BAD":
        return "#f44336";
      default:
        return "#9e9e9e";
    }
  };

  const getUtilizationColor = (utilization) => {
    if (utilization >= 100) return "#f44336"; // Red
    if (utilization >= 80) return "#ff9800"; // Orange
    return "#4caf50"; // Green
  };

  const getUtilizationSize = (utilization) => {
    // Scale marker size based on utilization (10-30px)
    return Math.max(10, Math.min(30, 10 + (utilization / 100) * 20));
  };

  // Create markers for stress data
  const createMarkers = () => {
    if (!stressData || stressData.length === 0) return [];

    return stressData.map((line, index) => {
      // For demo purposes, create mock coordinates based on line_id
      // In a real implementation, you'd get these from the GeoJSON data
      const mockCoords = [
        21.3 + (index % 10) * 0.1, // Latitude variation
        -157.9 + (index % 8) * 0.1, // Longitude variation
      ];

      return (
        <CircleMarker
          key={line.line_id}
          center={mockCoords}
          radius={getUtilizationSize(line.utilization_pct)}
          color={getUtilizationColor(line.utilization_pct)}
          fillColor={getUtilizationColor(line.utilization_pct)}
          fillOpacity={0.7}
          weight={2}
        >
          <Popup>
            <Box sx={{ minWidth: 200 }}>
              <Typography variant="h6" gutterBottom>
                Line: {line.line_id}
              </Typography>
              <Typography variant="body2" gutterBottom>
                <strong>From:</strong> {line.bus0_name} (Bus {line.bus0})<br />
                <strong>To:</strong> {line.bus1_name} (Bus {line.bus1})<br />
                <strong>Conductor:</strong> {line.conductor}
                <br />
                <strong>Voltage:</strong> {line.voltage_kv} kV
                <br />
                <strong>MOT:</strong> {line.mot_c}°C
              </Typography>
              <Box sx={{ mt: 1 }}>
                <Chip label={`${line.utilization_pct.toFixed(1)}% Utilization`} color={line.utilization_pct >= 100 ? "error" : line.utilization_pct >= 80 ? "warning" : "success"} size="small" />
              </Box>
              <Typography variant="body2" sx={{ mt: 1 }}>
                <strong>Rating:</strong> {line.rating_amps.toFixed(0)} A ({line.rating_mva.toFixed(1)} MVA)
                <br />
                <strong>Flow:</strong> {line.flow_amps.toFixed(0)} A ({line.flow_mva.toFixed(1)} MVA)
                <br />
                <strong>Margin:</strong> {(line.rating_amps - line.flow_amps).toFixed(0)} A
              </Typography>
            </Box>
          </Popup>
        </CircleMarker>
      );
    });
  };

  useEffect(() => {
    if (mapRef.current && stressData.length > 0) {
      // Fit map to show all markers
      const bounds = stressData.map((line, index) => [21.3 + (index % 10) * 0.1, -157.9 + (index % 8) * 0.1]);
      mapRef.current.fitBounds(bounds, { padding: [20, 20] });
    }
  }, [stressData]);

  return (
    <Box sx={{ height: "500px", position: "relative" }}>
      <Typography variant="h6" gutterBottom>
        Grid Line Status Map
      </Typography>

      {loading && (
        <Box
          sx={{
            position: "absolute",
            top: "50%",
            left: "50%",
            transform: "translate(-50%, -50%)",
            zIndex: 1000,
            backgroundColor: "rgba(255, 255, 255, 0.8)",
            borderRadius: 1,
            p: 2,
          }}
        >
          <CircularProgress />
          <Typography variant="body2" sx={{ mt: 1 }}>
            Loading data...
          </Typography>
        </Box>
      )}

      <MapContainer
        ref={mapRef}
        center={[21.3, -157.9]} // Honolulu coordinates
        zoom={8}
        style={{ height: "100%", width: "100%" }}
        bounds={hawaiiBounds}
        boundsOptions={{ padding: [20, 20] }}
      >
        <TileLayer attribution='&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors' url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png" />

        {/* Render markers for each line */}
        {createMarkers()}
      </MapContainer>

      {/* Legend */}
      <Box sx={{ mt: 2, display: "flex", gap: 1, flexWrap: "wrap" }}>
        <Typography variant="body2" sx={{ mr: 2 }}>
          <strong>Legend:</strong>
        </Typography>
        <Chip label="Good (<80%)" color="success" size="small" />
        <Chip label="Warning (80-100%)" color="warning" size="small" />
        <Chip label="Overloaded (≥100%)" color="error" size="small" />
        <Typography variant="body2" sx={{ ml: 2 }}>
          Marker size indicates utilization level
        </Typography>
      </Box>
    </Box>
  );
};

export { MapVisualization };
